// Run: node --test .github/scripts/
const test = require("node:test");
const assert = require("node:assert/strict");
const { checkBody, stripFooter, countLines, isBot } = require("./pr-rules.cjs");

const GOOD = `Adds a weekly issue.

Closes #12

**Tested:** dry runs.
**Not tested:** the timer.
`;

test("a complete description passes", () => {
	assert.deepEqual(checkBody(GOOD), []);
});

test("headings and list items count as sections", () => {
	const body = "Part of #4\n\n## Tested\n- x\n\n## Not tested\n- y";
	assert.deepEqual(checkBody(body), []);
});

test("each missing piece is reported", () => {
	const errors = checkBody("Just a description.");
	assert.equal(errors.length, 3);
	assert.match(errors[0], /Closes #N/);
});

test("'Not tested' alone does not count as 'Tested'", () => {
	const errors = checkBody("Closes #1\n**Not tested:** all");
	assert.equal(errors.length, 1);
	assert.match(errors[0], /"Tested"/);
});

test("closing keywords and 'Part of' link the issue; a bare number does not", () => {
	for (const link of ["Fixes #3", "resolves #3", "Closed #3", "part of #3"]) {
		assert.ok(
			!checkBody(`${link}\n${GOOD.replace("Closes #12", "")}`).some((e) =>
				/Link/.test(e),
			),
		);
	}
	assert.ok(
		checkBody(GOOD.replace("Closes #12", "See #12")).some((e) =>
			/Link/.test(e),
		),
	);
});

test("Claude Code footers and session links are removed", () => {
	const withFooter = `${GOOD}\n---\n_Generated by [Claude Code](https://claude.ai/code/session_01ABC)_\n`;
	assert.equal(stripFooter(withFooter), GOOD);
	const newStyle = `${GOOD}\n🤖 Generated with [Claude Code](https://claude.com/claude-code)\n\nhttps://claude.ai/code/session_01XYZ\n`;
	assert.equal(stripFooter(newStyle), GOOD);
	assert.equal(
		stripFooter(`${GOOD}Co-Authored-By: Claude <noreply@anthropic.com>\n`),
		GOOD,
	);
});

test("a description without a footer is left exactly as it is", () => {
	const body = "Text\n\n---\n\nMore text mentioning Claude Code in a sentence.";
	assert.equal(stripFooter(body), body);
	assert.equal(stripFooter(null), "");
});

test("lock files are left out of the size", () => {
	const files = [
		{ filename: "src/a.ts", additions: 300, deletions: 50 },
		{ filename: "package-lock.json", additions: 900, deletions: 900 },
		{ filename: "src-tauri/Cargo.lock", additions: 200, deletions: 0 },
		{ filename: "docs/b.md", additions: 10, deletions: 0 },
	];
	assert.equal(countLines(files), 360);
});

test("only Dependabot skips the description rules", () => {
	assert.equal(isBot({ user: { login: "dependabot[bot]" } }), true);
	assert.equal(isBot({ user: { login: "github-actions[bot]" } }), false);
	assert.equal(isBot({ user: { login: "T3rdfurgisun" } }), false);
	assert.equal(isBot({}), false);
});
